progressive_examples.raw_code:
// Khai báo giá trị giỏ hàng (VNĐ)
const cartAmount = 650000;

// Tính phí vận chuyển bằng toán tử ba ngôi
const shippingFee = cartAmount >= 500000 ? 0 : 30000;

// In thông tin thanh toán
console.log("Giá trị đơn hàng:", cartAmount, "VNĐ");
console.log("Phí vận chuyển áp dụng:", shippingFee, "VNĐ");

// Khai báo thông tin giỏ hàng và hạng thành viên
const cartAmount = 650000;
const customerTier = "VIP";

// Tính phí vận chuyển (Miễn phí nếu đơn từ 500,000 VNĐ)
const shippingFee = cartAmount >= 500000 ? 0 : 30000;

// Tính tỷ lệ giảm giá theo hạng thành viên
const discountRate = customerTier === "VIP" ? 0.10 : 0.05;

// Tính toán các khoản tiền
const discountAmount = cartAmount * discountRate;
const finalTotal = cartAmount - discountAmount + shippingFee;

console.log("Hạng khách hàng:", customerTier);
console.log("Số tiền được giảm:", discountAmount, "VNĐ");
console.log("Phí vận chuyển:", shippingFee, "VNĐ");
console.log("Tổng tiền cần thanh toán:", finalTotal, "VNĐ");

// Thông tin dữ liệu đơn hàng thực tế
const cartAmount = 1200000;
const customerTier = "VIP";
const paymentMethod = "COD";
const isOrderCancelled = false;

// 1. Kiểm tra điều kiện hợp lệ của đơn hàng bằng toán tử ba ngôi lồng nhau
const orderValidationMessage = isOrderCancelled
  ? "Đơn hàng đã bị hủy, không thể xử lý thanh toán."
  : cartAmount <= 0
  ? "Giá trị giỏ hàng không hợp lệ."
  : "Đơn hàng hợp lệ sẵn sàng tính toán.";

console.log("Trạng thái kiểm tra:", orderValidationMessage);

// 2. Tiến hành tính toán nếu đơn hàng hợp lệ
if (!isOrderCancelled && cartAmount > 0) {
  // Tính phí vận chuyển
  const shippingFee = cartAmount >= 500000 ? 0 : 30000;

  // Tính tỷ lệ giảm giá theo 3 cấp hạng thành viên
  const discountRate = customerTier === "DIAMOND"
    ? 0.15
    : customerTier === "VIP"
    ? 0.10
    : 0.05;

  // Tính phụ phí thanh toán dựa trên phương thức
  const paymentSurcharge = paymentMethod === "COD" ? 20000 : 0;

  // Số tiền giảm giá
  const discountAmount = cartAmount * discountRate;

  // Tổng số tiền thanh toán cuối cùng
  const finalTotal = cartAmount - discountAmount + shippingFee + paymentSurcharge;

  // Xác định độ ưu tiên xử lý đơn hàng
  const processingPriority = (customerTier === "VIP" || customerTier === "DIAMOND" || cartAmount >= 1000000)
    ? "HIGH"
    : "NORMAL";

  console.log("Tỷ lệ giảm giá áp dụng:", discountRate * 100 + "%");
  console.log("Số tiền được giảm:", discountAmount, "VNĐ");
  console.log("Phụ phí phương thức thanh toán:", paymentSurcharge, "VNĐ");
  console.log("Phí vận chuyển:", shippingFee, "VNĐ");
  console.log("Tổng tiền thanh toán cuối cùng:", finalTotal, "VNĐ");
  console.log("Độ ưu tiên xử lý đơn hàng:", processingPriority);
}

